<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ArrowLeft, Camera, KeyRound, Save, ShieldCheck } from '@lucide/vue'
import { api } from '../api'
import { useAuthStore } from '../stores/auth'

const auth = useAuthStore(); const saving = ref(false); const message = ref(''); const error = ref('')
const form = reactive({ displayName: '', email: '', phone: '', gender: 'UNDISCLOSED', birthDate: '', education: '', jobTitle: '', bio: '' })
const password = reactive({ currentPassword: '', newPassword: '', confirm: '' })
onMounted(() => Object.assign(form, { displayName: auth.user?.displayName || '', email: auth.user?.email || '', phone: auth.user?.phone || '', gender: auth.user?.gender || 'UNDISCLOSED', birthDate: auth.user?.birthDate || '', education: auth.user?.education || '', jobTitle: auth.user?.jobTitle || '', bio: auth.user?.bio || '' }))
async function saveProfile() { saving.value = true; error.value = ''; try { const { data } = await api.patch('/profile', form); auth.setUser(data); message.value = '个人资料已保存' } catch (e: any) { error.value = e.response?.data?.message || '保存失败' } finally { saving.value = false } }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const body = new FormData(); body.append('file', file); const { data } = await api.post('/profile/avatar', body); auth.setUser(data); message.value = '头像已更新' }
async function changePassword() { error.value = ''; if (password.newPassword !== password.confirm) { error.value = '两次输入的密码不一致'; return } try { await api.post('/auth/change-password', { currentPassword: password.currentPassword, newPassword: password.newPassword }); Object.assign(password, { currentPassword: '', newPassword: '', confirm: '' }); message.value = '密码已修改' } catch (e: any) { error.value = e.response?.data?.message || '密码修改失败' } }
</script>

<template><main class="settings-page"><header class="settings-header"><RouterLink to="/workspace"><ArrowLeft :size="18" />返回工作台</RouterLink><div><ShieldCheck /><span><small>HERCERT</small><strong>账号设置</strong></span></div></header><div class="settings-layout"><aside><div class="profile-summary"><span class="large-avatar">{{ auth.user?.displayName?.slice(0,1) }}</span><strong>{{ auth.user?.displayName }}</strong><small>{{ auth.user?.organizationName }}</small></div><a href="#profile" class="active">个人资料</a><a href="#security">账号与安全</a></aside><section class="settings-content"><div id="profile" class="settings-card"><div class="settings-title"><div><h2>个人资料</h2><p>管理您在安全工作台中展示的信息</p></div><label class="avatar-upload"><Camera :size="16" />更新头像<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload" /></label></div><form class="profile-form" @submit.prevent="saveProfile"><div class="field-grid"><label class="field"><span>登录用户名</span><input :value="auth.user?.username" disabled /></label><label class="field"><span>姓名 / 显示名称</span><input v-model="form.displayName" required /></label><label class="field"><span>所属组织</span><input :value="auth.user?.organizationName" disabled /></label><label class="field"><span>职务</span><input v-model="form.jobTitle" /></label><label class="field"><span>邮箱</span><input v-model="form.email" type="email" /></label><label class="field"><span>手机号</span><input v-model="form.phone" /></label><label class="field"><span>性别</span><select v-model="form.gender"><option value="UNDISCLOSED">不公开</option><option value="MALE">男</option><option value="FEMALE">女</option><option value="OTHER">其他</option></select></label><label class="field"><span>出生日期</span><input v-model="form.birthDate" type="date" /></label><label class="field"><span>学历</span><select v-model="form.education"><option value="">未填写</option><option>高中及以下</option><option>专科</option><option>本科</option><option>硕士</option><option>博士</option></select></label></div><label class="field"><span>个人简介</span><textarea v-model="form.bio" rows="3" maxlength="500"></textarea></label><button class="save-button" :disabled="saving"><Save :size="17" />{{ saving ? '保存中…' : '保存修改' }}</button></form></div><div id="security" class="settings-card"><div class="settings-title"><div><h2>账号与安全</h2><p>修改密码前需要验证当前密码</p></div><KeyRound /></div><form class="profile-form" @submit.prevent="changePassword"><div class="field-grid"><label class="field"><span>当前密码</span><input v-model="password.currentPassword" type="password" required /></label><span></span><label class="field"><span>新密码</span><input v-model="password.newPassword" type="password" minlength="10" required /></label><label class="field"><span>确认新密码</span><input v-model="password.confirm" type="password" minlength="10" required /></label></div><button class="save-button">修改密码</button></form></div><p v-if="message" class="floating-message success">{{ message }}</p><p v-if="error" class="floating-message error">{{ error }}</p></section></div></main></template>
